var so={id:"com.flickertalk.game.goalswipe",name:"Goal Swipe",version:"1.0.2",minCoreVersion:"1.6.0",kind:"game",icon:"football-outline",components:["ft-goalswipe"],permissions:{live:!0,send:"propose"},summary:"A penalty shoot-out for the whole family: swipe to shoot, tap to dive and save, five shots each, against FlickerTalk, two on one phone or with the other person in the chat.",locales:{es:{name:"Desliza y marca",summary:"Una tanda de penaltis para toda la familia: desliza para chutar, toca para lanzarte y parar, cinco tiros cada uno, contra FlickerTalk, dos en un mismo teléfono o con la otra persona del chat."},pt:{name:"Deslize e marque",summary:"Disputa de pênaltis para toda a família: deslize para chutar, toque para se atirar e defender, cinco chutes cada um, contra o FlickerTalk, a dois no mesmo telefone ou com a outra pessoa da conversa."},fr:{name:"Glisse et marque",summary:"Une séance de tirs au but pour toute la famille : glisse pour tirer, touche pour plonger et arrêter, cinq tirs chacun, contre FlickerTalk, à deux sur un téléphone ou avec l’autre personne du chat."},de:{name:"Wisch zum Tor",summary:"Ein Elfmeterschießen für die ganze Familie: Wisch zum Schießen, tipp zum Hechten und Halten, fünf Schüsse für jeden, gegen FlickerTalk, zu zweit an einem Handy oder mit der anderen Person im Chat."},it:{name:"Scorri e segna",summary:"Una sfida ai rigori per tutta la famiglia: scorri per tirare, tocca per tuffarti e parare, cinque tiri a testa, contro FlickerTalk, in due su un telefono o con l’altra persona della chat."},ro:{name:"Glisează și marchează",summary:"Penaltiuri pentru toată familia: glisează ca să șutezi, atinge ca să plonjezi și să aperi, cinci șuturi fiecare, contra lui FlickerTalk, în doi pe un telefon sau cu cealaltă persoană din conversație."},ru:{name:"Свайп и гол",summary:"Серия пенальти для всей семьи: проведи пальцем, чтобы ударить, коснись, чтобы прыгнуть и отбить, по пять ударов, против FlickerTalk, вдвоём на одном телефоне или с собеседником из чата."},uk:{name:"Свайп і гол",summary:"Серія пенальті для всієї родини: проведи пальцем, щоб ударити, торкнися, щоб стрибнути й відбити, по п’ять ударів, проти FlickerTalk, удвох на одному телефоні або з людиною з чату."},pl:{name:"Przesuń i strzel",summary:"Seria rzutów karnych dla całej rodziny: przesuń palcem, by strzelić, dotknij, by rzucić się i obronić, po pięć strzałów, przeciw FlickerTalk, we dwoje na jednym telefonie albo z drugą osobą z czatu."},tr:{name:"Kaydır, Gol At",summary:"Bütün aile için penaltı atışları: şut için kaydır, uçup kurtarmak için dokun, herkese beş atış; FlickerTalk'a karşı, tek telefonda iki kişi ya da sohbetteki kişiyle."},ar:{name:"اسحب وسجّل",summary:"ركلات ترجيح لكل العائلة: اسحب لتسدّد، والمس لتقفز وتتصدّى، خمس ركلات لكل لاعب، ضد FlickerTalk أو لاعبان على هاتف واحد أو مع الشخص الآخر في المحادثة."},hi:{name:"स्वाइप और गोल",summary:"पूरे परिवार के लिए पेनल्टी शूट-आउट: शॉट मारने के लिए स्वाइप करें, छलाँग लगाकर रोकने के लिए टैप करें, हर किसी के पाँच शॉट, FlickerTalk के ख़िलाफ़, एक ही फ़ोन पर दो लोग या चैट के दूसरे व्यक्ति के साथ।"},bn:{name:"সোয়াইপে গোল",summary:"পুরো পরিবারের জন্য পেনাল্টি শুট-আউট: শট নিতে সোয়াইপ করুন, ঝাঁপিয়ে ঠেকাতে ট্যাপ করুন, প্রত্যেকের পাঁচটি শট, FlickerTalk-এর বিরুদ্ধে, এক ফোনে দুজন বা চ্যাটের অন্যজনের সঙ্গে।"},id:{name:"Usap Jadi Gol",summary:"Adu penalti untuk seluruh keluarga: usap untuk menendang, ketuk untuk melompat dan menepis, lima tendangan masing-masing, melawan FlickerTalk, berdua di satu ponsel atau dengan orang lain di obrolan."},vi:{name:"Vuốt ghi bàn",summary:"Loạt sút luân lưu cho cả gia đình: vuốt để sút, chạm để bay người cản phá, mỗi người năm lượt, đấu với FlickerTalk, hai người trên một máy hoặc với người kia trong cuộc trò chuyện."},th:{name:"ปัดยิงประตู",summary:"ดวลจุดโทษสำหรับทั้งครอบครัว ปัดเพื่อยิง แตะเพื่อพุ่งเซฟ คนละห้าลูก เล่นกับ FlickerTalk เล่นสองคนบนเครื่องเดียว หรือกับอีกคนในแชท"},ja:{name:"スワイプゴール",summary:"家族みんなで楽しめる PK 戦。スワイプでシュート、タップで飛びついてセーブ。ひとり 5 本ずつ。FlickerTalk と、1 台でふたりで、またはチャットの相手と。"},ko:{name:"스와이프 골",summary:"온 가족이 즐기는 승부차기: 밀어서 슛하고, 눌러서 몸을 날려 막으세요. 각자 다섯 번씩, FlickerTalk와, 한 휴대폰에서 둘이, 또는 채팅 상대와 함께."},"zh-CN":{name:"滑动射门",summary:"适合全家的点球大战：滑动射门，点按扑救，每人五球，可以和 FlickerTalk 比、两人同用一部手机，或和聊天里的对方一起玩。"},"zh-TW":{name:"滑動射門",summary:"適合全家的 PK 大戰：滑動射門，點按撲救，每人五球，可以和 FlickerTalk 比、兩人共用一支手機，或和聊天裡的對方一起玩。"}}};var V=Math.PI*2,T=(e,t=0,n=1)=>Math.min(n,Math.max(t,Number.isFinite(e)?e:t)),ye=e=>1-(1-T(e))**3;var Fe=(e,t,n)=>e+(t-e)*n;function L(e,t,n,o,r,s){let i=Math.max(0,Math.min(Math.abs(o)/2,Math.abs(r)/2,s));e.beginPath(),e.moveTo(t+i,n),e.arcTo(t+o,n,t+o,n+r,i),e.arcTo(t+o,n+r,t,n+r,i),e.arcTo(t,n+r,t,n,i),e.arcTo(t,n,t+o,n,i),e.closePath()}var Tt=new WeakMap,$l=3;function hs(e,{ink:t,colour:n},o){if(!n)return o();let r=Tt.get(e);Tt.set(e,{ink:t,colour:n});try{return o()}finally{r?Tt.set(e,r):Tt.delete(e)}}function S(e,t,n,o){t&&(e.fillStyle=t,e.fill());let r=Tt.get(e);r&&n===r.ink&&o>0&&(e.strokeStyle=r.colour,e.lineWidth=o+$l,e.stroke()),n&&o>0&&(e.strokeStyle=n,e.lineWidth=o,e.stroke())}function k(e,t,n,o,r,s=null,i=0){e.beginPath(),e.arc(t,n,Math.max(0,o),0,V),S(e,r,s,i)}function tt(e,t,n,o,r,s,i=null,l=0){e.beginPath(),e.ellipse(t,n,Math.max(0,o),Math.max(0,r),0,0,V),S(e,s,i,l)}function nt(e,t,n,o=null,r=0){e.beginPath(),t.forEach(([s,i],l)=>l?e.lineTo(s,i):e.moveTo(s,i)),e.closePath(),S(e,n,o,r)}function M(e,t,n,o){e.beginPath(),t.forEach(([r,s],i)=>i?e.lineTo(r,s):e.moveTo(r,s)),e.strokeStyle=n,e.lineWidth=o,e.lineCap="round",e.lineJoin="round",e.stroke()}function ot(e,t,n,o,r=o*.46){e.beginPath();for(let s=0;s<10;s+=1){let i=s%2?r:o,l=-Math.PI/2+s*Math.PI/5,a=t+Math.cos(l)*i,c=n+Math.sin(l)*i;s?e.lineTo(a,c):e.moveTo(a,c)}e.closePath()}function ps(e,t,n,o){let r=Math.max(20,Math.min(38,n*.055))/3;e.save(),e.fillStyle=o,[1,.72,.36].forEach((s,i)=>{i&&(e.globalAlpha=s),e.fillRect(0,i*r,t,r),e.fillRect(0,n-(i+1)*r,t,r)}),e.restore()}function rt(e){let t=Math.sin(e*127.1+311.7)*43758.5453;return t-Math.floor(t)}var io=e